import{_ as t,c as a,o as i,a5 as o}from"./chunks/framework.DYgWcJ6Z.js";const p=JSON.parse('{"title":"Integration with Unity","description":"","frontmatter":{},"headers":[],"relativePath":"manual/runtime/integrate-runtime-with-unity.md","filePath":"manual/runtime/integrate-runtime-with-unity.md","lastUpdated":1754235051000}'),n={name:"manual/runtime/integrate-runtime-with-unity.md"};function r(s,e,d,l,h,c){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="integration-with-unity" tabindex="-1">Integration with Unity <a class="header-anchor" href="#integration-with-unity" aria-label="Permalink to &quot;Integration with Unity&quot;">​</a></h1><p>In addition to the official methods of running JSAR, we also support integration with Unity for developers who want to extend JSAR&#39;s runtime platform.</p><blockquote><p>This chapter is intended for readers with a basic understanding of Unity. If you are unfamiliar with Unity, we recommend learning its basics first.</p></blockquote><blockquote><p>We do not currently provide a public Unity integration SDK. If needed, please contact us through Discord or GitHub to request the SDK and intermediate protocols.</p></blockquote><h2 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h2><p>JSAR&#39;s Unity SDK supports the following platforms:</p><ul><li>Windows x86_64</li><li>MacOS x86_64</li><li>MacOS arm64 (M series)</li><li>Android arm64</li></ul><h2 id="pipeline-support" tabindex="-1">Pipeline Support <a class="header-anchor" href="#pipeline-support" aria-label="Permalink to &quot;Pipeline Support&quot;">​</a></h2><p>Currently, JSAR supports the following Unity pipelines:</p><ul class="task-list"><li class="task-list-item"><input type="checkbox" id="cbx_0" checked="true" disabled="true"><label for="cbx_0"> Built-in Render Pipeline</label></li><li class="task-list-item"><input type="checkbox" id="cbx_1" disabled="true"><label for="cbx_1"> Universal Render Pipeline</label></li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>After obtaining the UPM package, install it locally in Unity.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>You can use JSAR&#39;s Unity SDK in various ways.</p><h3 id="prefabs" tabindex="-1">Prefabs <a class="header-anchor" href="#prefabs" aria-label="Permalink to &quot;Prefabs&quot;">​</a></h3><p>You can use the &quot;Prefabs/TransmuteBow.prefab,&quot; which represents an instance of a spatial app. Once initialized, you can use it.</p><h3 id="scripts" tabindex="-1">Scripts <a class="header-anchor" href="#scripts" aria-label="Permalink to &quot;Scripts&quot;">​</a></h3><p>The prefabs are essentially implemented by attaching the &quot;Scripts/Transmute.cs&quot; script. You can also directly attach this script to any game object and control it through code.</p><p>We provide some configurable parameters.</p><h4 id="static-parameter-string-applicationcachedirectory" tabindex="-1">Static Parameter <code>string ApplicationCacheDirectory</code> <a class="header-anchor" href="#static-parameter-string-applicationcachedirectory" aria-label="Permalink to &quot;Static Parameter `string ApplicationCacheDirectory`&quot;">​</a></h4><p>With this parameter, you can specify the cache directory for JSAR, used to store JSAR&#39;s resource files, such as model files, textures, scripts, audio, etc.</p><h4 id="static-parameter-bool-enableloggingofcorebydefault-false" tabindex="-1">Static Parameter <code>bool EnableLoggingOfCoreByDefault = false</code> <a class="header-anchor" href="#static-parameter-bool-enableloggingofcorebydefault-false" aria-label="Permalink to &quot;Static Parameter `bool EnableLoggingOfCoreByDefault = false`&quot;">​</a></h4><p>With this parameter, you can specify whether JSAR should enable logging by default.</p><h4 id="string-scriptname" tabindex="-1"><code>string ScriptName</code> <a class="header-anchor" href="#string-scriptname" aria-label="Permalink to &quot;`string ScriptName`&quot;">​</a></h4><p>If you are using the prefab method, you can configure this parameter to specify the path of the XSML file to run, supporting both local and network paths.</p><h4 id="bool-autostart-true" tabindex="-1"><code>bool AutoStart = true</code> <a class="header-anchor" href="#bool-autostart-true" aria-label="Permalink to &quot;`bool AutoStart = true`&quot;">​</a></h4><p>If you are using the prefab method, you can configure this parameter to specify whether the XSML file should start running automatically.</p><h4 id="material-defaultmat" tabindex="-1"><code>Material DefaultMat</code> <a class="header-anchor" href="#material-defaultmat" aria-label="Permalink to &quot;`Material DefaultMat`&quot;">​</a></h4><p>Default material, initially a dynamically created Standard material. You can also specify your own material using this parameter, and it will be used to create materials for each app.</p><h4 id="material-defaultlinemat" tabindex="-1"><code>Material DefaultLineMat</code> <a class="header-anchor" href="#material-defaultlinemat" aria-label="Permalink to &quot;`Material DefaultLineMat`&quot;">​</a></h4><p>Default line material, initially a dynamically created Line material. You can specify your own material using this parameter, and it will be used to create line materials for each app.</p><h4 id="bool-usetransformtoreact-false" tabindex="-1"><code>bool UseTransformToReact = false</code> <a class="header-anchor" href="#bool-usetransformtoreact-false" aria-label="Permalink to &quot;`bool UseTransformToReact = false`&quot;">​</a></h4><p>JSAR scales objects based on their Bounding Box after loading to ensure consistent sizes. There are two scaling options: one based on the parent object&#39;s transform and the other based on the Box Collider. You can specify which one to use with this parameter.</p><h4 id="static-method-void-dispatchmousemoveevent-vector3-mouseposition" tabindex="-1">Static Method <code>void DispatchMouseMoveEvent(Vector3 mousePosition)</code> <a class="header-anchor" href="#static-method-void-dispatchmousemoveevent-vector3-mouseposition" aria-label="Permalink to &quot;Static Method `void DispatchMouseMoveEvent(Vector3 mousePosition)`&quot;">​</a></h4><p>Use this method to dispatch mouse move events. If you want your app to respond to mouse movement events in your runtime environment, you can use this method to dispatch mouse move events.</p><h4 id="static-method-void-dispatchmouseaction-string-actionvalue" tabindex="-1">Static Method <code>void DispatchMouseAction(string actionValue)</code> <a class="header-anchor" href="#static-method-void-dispatchmouseaction-string-actionvalue" aria-label="Permalink to &quot;Static Method `void DispatchMouseAction(string actionValue)`&quot;">​</a></h4><p>Similar to the previous method but for dispatching mouse keyup and keydown events.</p><h4 id="static-method-void-dispatchhandtracking-int-handtype-vector3-handjoints-pose-handpose-int-handgesture-int-handorientation-bool-isnearinteraction" tabindex="-1">Static Method <code>void DispatchHandTracking(int handType, Vector3[] handJoints, Pose handPose, int handGesture, int handOrientation, bool isNearInteraction)</code> <a class="header-anchor" href="#static-method-void-dispatchhandtracking-int-handtype-vector3-handjoints-pose-handpose-int-handgesture-int-handorientation-bool-isnearinteraction" aria-label="Permalink to &quot;Static Method `void DispatchHandTracking(int handType, Vector3[] handJoints, Pose handPose, int handGesture, int handOrientation, bool isNearInteraction)`&quot;">​</a></h4><p>Used to dispatch hand tracking events. If you want your app to respond to hand gestures, you need to call this method when updating hand gestures. The parameters are as follows:</p><ul><li><code>int handType</code>: Hand type, 0 for left hand, 1 for right hand.</li><li><code>Vector3[] handJoints</code>: Hand joints, including 21 joints, each represented as a Vector3 with x, y, and z coordinates.</li><li><code>Pose handPose</code>: Hand position and rotation information.</li><li><code>int handGesture</code>: Hand gesture type, 0 for no gesture, 1 for finger, 2 for palm.</li><li><code>int handOrientation</code>: Hand orientation, 0 for palm down, 1 for palm up.</li><li><code>bool isNearInteraction</code>: Whether it&#39;s a near interaction. If true, the hand tracking coordinate system will be transformed based on the hand&#39;s position to ensure that the coordinate system always faces forward.</li></ul><h4 id="static-method-void-dispatchhandray-int-handtype-ray-handray" tabindex="-1">Static Method <code>void DispatchHandRay(int handType, Ray handRay)</code> <a class="header-anchor" href="#static-method-void-dispatchhandray-int-handtype-ray-handray" aria-label="Permalink to &quot;Static Method `void DispatchHandRay(int handType, Ray handRay)`&quot;">​</a></h4><p>Used to dispatch ray events. Internally, JSAR uses rays to interact with objects and UI. You can use this method to dispatch your ray information to JSAR. The parameters are as follows:</p><ul><li><code>int handType</code>: Hand type, 0 for left hand, 1 for right hand.</li><li><code>Ray handRay</code>: Ray information, including the starting point and direction of the ray.</li></ul><h4 id="static-method-void-dispatchhandpress-int-handtype-int-offset" tabindex="-1">Static Method <code>void DispatchHandPress(int handType, int offset)</code> <a class="header-anchor" href="#static-method-void-dispatchhandpress-int-handtype-int-offset" aria-label="Permalink to &quot;Static Method `void DispatchHandPress(int handType, int offset)`&quot;">​</a></h4><p>Similar to the previous method, JSAR internally uses the ray to determine selected objects and UI, and uses Press to determine whether a click occurred.</p><ul><li><code>int handType</code>: Hand type, 0 for left hand, 1 for right hand.</li><li><code>int offset</code>: Optional.</li></ul><h4 id="static-method-void-dispatchhandrelease-int-handtype-int-offset" tabindex="-1">Static Method <code>void DispatchHandRelease(int handType, int offset)</code> <a class="header-anchor" href="#static-method-void-dispatchhandrelease-int-handtype-int-offset" aria-label="Permalink to &quot;Static Method `void DispatchHandRelease(int handType, int offset)`&quot;">​</a></h4><p>Similar to the previous method, JSAR internally uses the ray to determine selected objects and UI, and uses Release to determine whether a click occurred.</p><ul><li><code>int handType</code>: Hand type, 0 for left hand, 1 for right hand.</li><li><code>int offset</code>: Optional.</li></ul><h3 id="other-methods" tabindex="-1">Other Methods <a class="header-anchor" href="#other-methods" aria-label="Permalink to &quot;Other Methods&quot;">​</a></h3><p>You can also modify and extend JSAR&#39;s Unity SDK according to your needs.</p><h2 id="how-unity-interacts-with-jsar" tabindex="-1">How Unity Interacts with JSAR <a class="header-anchor" href="#how-unity-interacts-with-jsar" aria-label="Permalink to &quot;How Unity Interacts with JSAR&quot;">​</a></h2><p>In JSAR, achieving simple interaction between Unity and JSAR apps, such as rotation, movement, and scaling, is straightforward. You only need to manipulate the container nodes as per your requirements, without any additional steps.</p><h2 id="including-necessary-shaders" tabindex="-1">Including Necessary Shaders <a class="header-anchor" href="#including-necessary-shaders" aria-label="Permalink to &quot;Including Necessary Shaders&quot;">​</a></h2><p>Because JSAR dynamically loads objects, when integrating into a Unity application, you need to manually include some shaders to ensure the proper rendering of JSAR apps:</p><ul><li><code>Standard</code>: Used for basic material. If you use custom materials, you can exclude this shader.</li><li><code>Wireframe/Cull</code>: Used for rendering wireframes.</li><li><code>Wireframe/NoCull</code>: Used for rendering wireframes.</li></ul><p>Please feel free to ask if you have any further questions or need additional information.</p>',57)]))}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
